import{_ as t,o as i,c as o,a2 as r}from"./chunks/framework.DNL3hc5c.js";const h=JSON.parse('{"title":"Security Policy","description":"","frontmatter":{},"headers":[],"relativePath":"SECURITY.md","filePath":"SECURITY.md"}'),a={name:"SECURITY.md"};function s(l,e,n,u,c,d){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="security-policy" tabindex="-1">Security Policy <a class="header-anchor" href="#security-policy" aria-label="Permalink to &quot;Security Policy&quot;">​</a></h1><h2 id="supported-versions" tabindex="-1">Supported Versions <a class="header-anchor" href="#supported-versions" aria-label="Permalink to &quot;Supported Versions&quot;">​</a></h2><p>The following table lists the versions of Magma projects that currently receive security updates:</p><table tabindex="0"><thead><tr><th>Version</th><th>Supported</th></tr></thead><tbody><tr><td>4.x</td><td>✅</td></tr><tr><td>&lt; 4.0</td><td>❌</td></tr></tbody></table><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a Vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a Vulnerability&quot;">​</a></h2><p>We take the security of Magma Computing projects and <code>@magmacomputing/tempo</code> seriously. If you believe you have discovered a security vulnerability, please follow responsible disclosure guidelines.</p><h3 id="how-to-report" tabindex="-1">How to Report <a class="header-anchor" href="#how-to-report" aria-label="Permalink to &quot;How to Report&quot;">​</a></h3><p><strong>Do NOT report security vulnerabilities through public GitHub issues.</strong></p><p>Instead, please report security issues by emailing our security team at: <code>security@magmacomputing.com.au</code></p><p>Alternatively, you may submit a private security advisory through the <strong>Security</strong> tab of our GitHub repository: <a href="https://github.com/magmacomputing/magma/security/advisories/new" target="_blank" rel="noreferrer">Submit Security Advisory</a>.</p><h3 id="what-to-include" tabindex="-1">What to Include <a class="header-anchor" href="#what-to-include" aria-label="Permalink to &quot;What to Include&quot;">​</a></h3><p>To help us investigate and resolve the issue quickly, please include:</p><ul><li>A detailed description of the vulnerability and potential impact.</li><li>Step-by-step instructions or proof-of-concept (PoC) code to reproduce the issue.</li><li>The package name and version affected (e.g. <code>@magmacomputing/tempo@4.0.1</code>).</li><li>Any potential mitigations or suggested fixes.</li></ul><h3 id="response-timeline" tabindex="-1">Response Timeline <a class="header-anchor" href="#response-timeline" aria-label="Permalink to &quot;Response Timeline&quot;">​</a></h3><ul><li><strong>Acknowledgement:</strong> We will acknowledge receipt of your vulnerability report within <strong>48 hours</strong>.</li><li><strong>Assessment &amp; Fix:</strong> We aim to assess and patch verified vulnerabilities within <strong>7 business days</strong>.</li><li><strong>Public Disclosure:</strong> Public advisories and patched releases will be coordinated with the reporter after a fix is verified and deployed.</li></ul><p>Thank you for helping keep the open-source ecosystem secure!</p>',16)])])}const m=t(a,[["render",s]]);export{h as __pageData,m as default};
